 public CatalogPage Search(string search,int offset=0,int limit=200,CatalogFilter? filter=null, CancellationToken cancellationToken=default)
 {
  cancellationToken.ThrowIfCancellationRequested();
  if(offset<0||limit<1||limit>1000)throw new ArgumentOutOfRangeException(nameof(limit),"Sayfa boyutu 1–1000, başlangıç sıfır veya daha büyük olmalı.");
  filter??=new();
  foreach(var values in new[]{filter.Brands,filter.Categories,filter.Skus,filter.SourceIds})if(values.Length>100||values.Sum(v=>v.Length)>6000)throw new ArgumentException("Filtre en fazla 100 değer ve 6000 karakter olabilir.");
  using var c=Open();using var tx=c.BeginTransaction(deferred:true);
  // Substring search cannot use a B-tree index; filter/count in SQLite and deserialize only the requested page.
  var where=" WHERE ($all=1 OR uifold(json_extract(Json,'$.Name')) LIKE $q ESCAPE '\\' OR uifold(json_extract(Json,'$.Sku')) LIKE $q ESCAPE '\\' OR uifold(json_extract(Json,'$.Barcode')) LIKE $q ESCAPE '\\' OR uifold(json_extract(Json,'$.Brand')) LIKE $q ESCAPE '\\' OR uifold(json_extract(Json,'$.Category')) LIKE $q ESCAPE '\\'";
  where += ") AND ($active=-1 OR COALESCE(json_extract(Json,'$.Active'),1)=$active) AND ($description=-1 OR (length(trim(COALESCE(json_extract(Json,'$.Description'),'')))>0)=$description) AND ($image=-1 OR (length(trim(COALESCE(json_extract(Json,'$.ImageUrls'),'')))>0)=$image) AND ($minPrice IS NULL OR json_extract(Json,'$.Price') >= $minPrice) AND ($maxPrice IS NULL OR json_extract(Json,'$.Price') <= $maxPrice) AND ($minCost IS NULL OR json_extract(Json,'$.Cost') >= $minCost) AND ($maxCost IS NULL OR json_extract(Json,'$.Cost') <= $maxCost) AND ($minStock IS NULL OR json_extract(Json,'$.Stock') >= $minStock) AND ($maxStock IS NULL OR json_extract(Json,'$.Stock') <= $maxStock) AND ($sourceMissing IS NULL OR COALESCE(json_extract(Json,'$.SourceMissing'),0)=$sourceMissing)";
  var extra=new Dictionary<string,string>();
  foreach(var (field,values) in new[]{("Brand",filter.Brands),("Category",filter.Categories),("Sku",filter.Skus),("SourceId",filter.SourceIds)}){
   if(values.Length==0)continue;
   var names=new List<string>();foreach(var value in values){var clean=value.Trim();if(clean.Length==0)continue;var key="$filter"+extra.Count;extra.Add(key,clean);names.Add(key);}if(names.Count==0)continue;
   where+=$" AND json_extract(Json,'$.{field}') COLLATE NOCASE IN ({string.Join(",",names)})";
  }
  search=search.Trim();var pattern="%"+UiSearch.Fold(search).Replace("\\","\\\\").Replace("%","\\%").Replace("_","\\_")+"%";
  void Params(SqliteCommand cmd){cmd.Transaction=tx;cmd.Parameters.AddWithValue("$all",search.Length==0?1:0);cmd.Parameters.AddWithValue("$q",pattern);cmd.Parameters.AddWithValue("$active",filter.Active.HasValue?(filter.Active.Value?1:0):-1);cmd.Parameters.AddWithValue("$description",filter.DescriptionPresent.HasValue?(filter.DescriptionPresent.Value?1:0):-1);cmd.Parameters.AddWithValue("$image",filter.ImagePresent.HasValue?(filter.ImagePresent.Value?1:0):-1);cmd.Parameters.AddWithValue("$minPrice",(object?)filter.MinPrice??DBNull.Value);cmd.Parameters.AddWithValue("$maxPrice",(object?)filter.MaxPrice??DBNull.Value);cmd.Parameters.AddWithValue("$minCost",(object?)filter.MinCost??DBNull.Value);cmd.Parameters.AddWithValue("$maxCost",(object?)filter.MaxCost??DBNull.Value);cmd.Parameters.AddWithValue("$minStock",(object?)filter.MinStock??DBNull.Value);cmd.Parameters.AddWithValue("$maxStock",(object?)filter.MaxStock??DBNull.Value);cmd.Parameters.AddWithValue("$sourceMissing",filter.SourceMissing.HasValue?(filter.SourceMissing.Value?1:0):DBNull.Value);foreach(var pair in extra)cmd.Parameters.AddWithValue(pair.Key,pair.Value);}
  int total,inStock,linked;
  using(var count=c.CreateCommand()){cancellationToken.ThrowIfCancellationRequested();Params(count);count.CommandText="SELECT COUNT(*),COALESCE(SUM(CASE WHEN json_extract(Json,'$.Stock')>0 THEN 1 ELSE 0 END),0),COALESCE(SUM(CASE WHEN COALESCE(json_extract(Json,'$.EtsyListingId'),'')<>'' THEN 1 ELSE 0 END),0) FROM CatalogProducts"+where;using var reader=count.ExecuteReader();reader.Read();total=reader.GetInt32(0);inStock=reader.GetInt32(1);linked=reader.GetInt32(2);}
  var sort = filter.SortBy.Trim().ToLowerInvariant() switch { "sku" => "Sku", "barcode" => "Barcode", "price" => "Price", "cost" => "Cost", "stock" => "Stock", "updated" => "UpdatedUtc", _ => "Name" }; var direction = filter.SortDescending ? " DESC" : " ASC";
  var items=new List<CatalogProduct>();using(var page=c.CreateCommand()){cancellationToken.ThrowIfCancellationRequested();Params(page);page.CommandText="SELECT Json FROM CatalogProducts"+where+$" ORDER BY json_extract(Json,'$.{sort}') COLLATE NOCASE{direction},Id LIMIT $limit OFFSET $offset";page.Parameters.AddWithValue("$limit",limit);page.Parameters.AddWithValue("$offset",offset);using var reader=page.ExecuteReader();while(reader.Read()){cancellationToken.ThrowIfCancellationRequested();items.Add(JsonSerializer.Deserialize<CatalogProduct>(reader.GetString(0))!);}}
