 public List<XmlSource> Sources(){using var c=Open();return Read<XmlSource>(c,"Sources");}
 public void SaveSource(XmlSource source)=>SaveSource(source,SourceRevisionStore.SaveReason);
 // #893: every configuration change is one immutable revision written in the same transaction as the source; a state-only save appends nothing; a record loaded at a revision that is no longer current is a concurrent edit and is refused before anything is written (a never-loaded record carries no expectation).
 public void SaveSource(XmlSource source,string reason){XmlCatalog.ValidateSource(source);if(string.IsNullOrWhiteSpace(source.Id))throw new InvalidOperationException("Kaynak kimliği boş.");using var c=Open();using var tx=c.BeginTransaction();using var find=c.CreateCommand();find.Transaction=tx;find.CommandText="SELECT Json FROM Sources WHERE Id=$id";find.Parameters.AddWithValue("$id",source.Id);if(find.ExecuteScalar() is string json){var old=JsonSerializer.Deserialize<XmlSource>(json)!;if(source.ConfigRevision>0&&source.ConfigRevision!=old.ConfigRevision)throw new SourceRevisionConflictException(source.ConfigRevision,old.ConfigRevision);if(!MappingEquivalent(old,source))source.MappingRevision=Math.Max(source.MappingRevision,old.MappingRevision)+1;source.LastAppliedMappingRevision=Math.Max(source.LastAppliedMappingRevision,old.LastAppliedMappingRevision);if(string.IsNullOrWhiteSpace(source.LastMappingShapeFingerprint))source.LastMappingShapeFingerprint=old.LastMappingShapeFingerprint;if(string.IsNullOrWhiteSpace(source.LastSuccessfulFeedHash))source.LastSuccessfulFeedHash=old.LastSuccessfulFeedHash;if(source.LastSuccessfulFeedUtc is null)source.LastSuccessfulFeedUtc=old.LastSuccessfulFeedUtc;if(source.LastSuccessfulFeedCount==0)source.LastSuccessfulFeedCount=old.LastSuccessfulFeedCount;if(source.LastFeedState=="NEVER")source.LastFeedState=old.LastFeedState;}source.ConfigRevision=SourceRevisionStore.Append(c,tx,source,reason);Put(c,"Sources",source.Id,source,tx);tx.Commit();}
 public IReadOnlyList<SourceRevisionSnapshot> SourceRevisions(string sourceId){using var c=Open();return SourceRevisionStore.List(c,sourceId);}
 public SourceRevisionSnapshot? SourceRevision(string sourceId,int revision){using var c=Open();return SourceRevisionStore.Get(c,sourceId,revision);}
 // #893: a rollback never rewrites history -- the chosen revision's configuration goes onto the current record and the save appends a new revision naming it.
 public XmlSource RestoreSourceRevision(string sourceId,int revision){var current=Sources().FirstOrDefault(x=>x.Id==sourceId)??throw new InvalidOperationException("Kaynak bulunamadı.");var snapshot=SourceRevision(sourceId,revision)??throw new InvalidOperationException($"Kaynağın {revision} numaralı sürümü yok.");var config=snapshot.Config??throw new InvalidOperationException("Sürüm kaydı okunamadı.");config.ApplyTo(current);SaveSource(current,$"geri alma: rev. {revision}");return current;}
 // #895: the fields a feed writes on a new product -- every one it maps; an existing product's written set is decided field by field above.
 static IEnumerable<string> WrittenFields(XmlSource source,CatalogProduct? old){var fields=new List<string>{"Cost","Price","Currency","Stock","Name","Description","ImageUrls"};if(source.Fields.ContainsKey("Gtin"))fields.Add("Gtin");return fields;}
 // #896: a decision's words go onto the field's origin -- the winner's when the feed wrote it, the holder's when the feed was refused -- so the product carries the explanation across a restart; true when any words changed.
 static bool MarkDecisions(CatalogProduct product,IReadOnlyList<SourcePriorityDecision> marks,Func<string,string> nameOf){if(marks.Count==0)return false;var changed=false;product.FieldOrigins??=new Dictionary<string,FieldOrigin>(StringComparer.Ordinal);foreach(var d in marks){if(!product.FieldOrigins.TryGetValue(d.Field,out var origin)){origin=new FieldOrigin{Kind=FieldProvenance.ManualKind,ObservedUtc=d.DecidedUtc};product.FieldOrigins[d.Field]=origin;changed=true;}var words=d.Words(nameOf);if(origin.Decision!=words){origin.Decision=words;changed=true;}}return changed;}
 void WriteDecisions(IReadOnlyList<SourcePriorityDecision> decisions,Func<string,string> nameOf){if(decisions.Count==0)return;try{var audit=new AuditStore(dataDirectory);foreach(var d in decisions)audit.Append(SourcePriority.ToAudit(d,nameOf));}catch(Exception){}}
